                <ValidationMessage For="() => model.PreferredSession" />
            </div>

            <div class="mb-3">
                <label for="dietary" class="form-label">Special Dietary Requirements</label>
                <InputTextArea id="dietary" class="form-control" @bind-Value="model.DietaryRequirements" rows="3" />
            </div>

            <button type="submit" class="btn btn-primary" disabled="@isProcessing">
                @if (isProcessing)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                }
                Register
            </button>
        </EditForm>
    }
</div>

@code {
    private RegistrationModel model = new();
    private string? emailServerError;
    private bool isProcessing;
    private bool isSubmitted;

    private async Task HandleSubmit()
    {
        emailServerError = null;
        isProcessing = true;

        try
        {
            var serverErrors = await RegistrationService.ValidateAsync(model.Email);

            if (serverErrors.TryGetValue("Email", out var emailError))
            {
                emailServerError = emailError;
                return;
            }

            // Registration would be saved here
            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

